  1→/**
  2→ * Search Index Service
  3→ *
  4→ * Manages a client-side search index for file and folder names using MiniSearch.
  5→ * The index is encrypted with AES-256-GCM (key derived via HKDF from the user's
  6→ * vault private key) before persisting to IndexedDB for zero-knowledge on-disk storage.
  7→ *
  8→ * This is a pure TypeScript service with no React dependencies.
  9→ */
 10→
 11→import MiniSearch from 'minisearch';
 12→import type { FolderNode } from '../stores/folder.store';
 13→
 14→// ---------------------------------------------------------------------------
 15→// Types
 16→// ---------------------------------------------------------------------------
 17→
 18→/** A document stored in the MiniSearch index. */
 19→type SearchDocument = {
 20→  /** Unique key: `${folderId}:${childId}` (avoids collisions across folders) */
 21→  id: string;
 22→  /** File or folder name (what users search for) */
 23→  name: string;
 24→  /** Whether this is a file or folder */
 25→  type: 'file' | 'folder';
 26→  /** Breadcrumb path like "My Vault / Documents / Reports" */
 27→  parentPath: string;
 28→  /** Folder ID for navigation on result click */
 29→  parentFolderId: string;
 30→  /** Timestamp for display in results (Unix ms) */
 31→  modifiedAt: number;
 32→};
 33→
 34→/** A search result returned by the service. */
 35→export type SearchResult = {
 36→  id: string;
 37→  name: string;
 38→  type: 'file' | 'folder';
 39→  parentPath: string;
 40→  parentFolderId: string;
 41→  modifiedAt: number;
 42→  /** MiniSearch relevance score (higher = better match) */
 43→  score: number;
 44→  /** Match info from MiniSearch, maps field name to matching terms */
 45→  match: Record<string, string[]>;
 46→};
 47→
 48→// ---------------------------------------------------------------------------
 49→// MiniSearch options (shared between constructor and loadJSON)
 50→// ---------------------------------------------------------------------------
 51→
 52→const MINISEARCH_OPTIONS = {
 53→  fields: ['name'],
 54→  storeFields: ['name', 'type', 'parentPath', 'parentFolderId', 'modifiedAt'],
 55→  searchOptions: {
 56→    fuzzy: 0.2,
 57→    prefix: true,
 58→    boost: { name: 1 },
 59→  },
 60→};
 61→
 62→// ---------------------------------------------------------------------------
 63→// IndexedDB constants
 64→// ---------------------------------------------------------------------------
 65→
 66→const IDB_NAME = 'cipherbox-search';
 67→const IDB_VERSION = 1;
 68→const IDB_STORE = 'index';
 69→const IDB_KEY = 'encrypted-index';
 70→
 71→// ---------------------------------------------------------------------------
 72→// HKDF constants
 73→// ---------------------------------------------------------------------------
 74→
 75→const HKDF_INFO = 'cipherbox-search-index-v1';
 76→
 77→// ---------------------------------------------------------------------------
 78→// IndexedDB helpers (follows pattern from device/identity.ts)
 79→// ---------------------------------------------------------------------------
 80→
 81→function openSearchDB(): Promise<IDBDatabase> {
 82→  return new Promise((resolve, reject) => {
 83→    const request = indexedDB.open(IDB_NAME, IDB_VERSION);
 84→    request.onupgradeneeded = () => {
 85→      request.result.createObjectStore(IDB_STORE);
 86→    };
 87→    request.onsuccess = () => resolve(request.result);
 88→    request.onerror = () => reject(request.error);
 89→  });
 90→}
 91→
 92→// ---------------------------------------------------------------------------
 93→// SearchIndexService
 94→// ---------------------------------------------------------------------------
 95→
 96→export class SearchIndexService {
 97→  private miniSearch: MiniSearch<SearchDocument>;
 98→  private indexVersion: number = 0;
 99→
100→  constructor() {
101→    this.miniSearch = new MiniSearch<SearchDocument>(MINISEARCH_OPTIONS);
102→  }
103→
104→  /**
105→   * Build the full index from the folder store's folder tree.
106→   * Walks all loaded FolderNodes and indexes their children (files and folders).
107→   *
108→   * @param folders - Record<string, FolderNode> from folder store
109→   */
110→  buildFromFolderTree(folders: Record<string, FolderNode>): void {
111→    // Diagnostic: log what we're building from
112→    const folderIds = Object.keys(folders);
113→    const rootChildren = (folders['root']?.children ?? []).map((c) => c.name);
114→    console.log(
115→      `[SearchIndex.build] folders=${folderIds.length} rootChildren=${rootChildren.length}: [${rootChildren.join(',')}]`
116→    );
117→    console.trace('[SearchIndex.build] call stack');
118→
119→    this.miniSearch.removeAll();
120→
121→    const documents: SearchDocument[] = [];
122→
123→    for (const folder of Object.values(folders)) {
124→      const parentPath = this.buildPath(folder.id, folders);
125→
126→      // Index each child (files and subfolders)
127→      for (const child of folder.children) {
128→        documents.push({
129→          id: `${folder.id}:${child.id}`,
130→          name: child.name,
131→          type: child.type === 'folder' ? 'folder' : 'file',
132→          parentPath,
133→          parentFolderId: folder.id,
134→          modifiedAt: child.modifiedAt ?? child.createdAt ?? 0,
135→        });
136→      }
137→    }
138→
139→    // Also index folders themselves (except root) as searchable items.
140→    // A folder's parent is its parentId, so it appears in search under
141→    // the parent folder's path.
142→    for (const folder of Object.values(folders)) {
143→      if (!folder.parentId) continue; // skip root
144→      const parentFolder = folders[folder.parentId];
145→      if (!parentFolder) continue;
146→
147→      const parentPath = this.buildPath(folder.parentId, folders);
148→
149→      // Use the folder's own id with a "self:" prefix to avoid collision
150→      // with the same folder appearing as a child entry
151→      documents.push({
152→        id: `${folder.parentId}:${folder.id}`,
153→        name: folder.name,
154→        type: 'folder',
155→        parentPath,
156→        parentFolderId: folder.parentId,
157→        modifiedAt: 0, // folders don't have a top-level modifiedAt
158→      });
159→    }
160→
161→    // Deduplicate: children already include subfolder entries from parent.
162→    // The folder-self entries above may overlap with child entries.
163→    // Use a Map to keep only one document per id.
164→    const deduped = new Map<string, SearchDocument>();
165→    for (const doc of documents) {
166→      if (!deduped.has(doc.id)) {
167→        deduped.set(doc.id, doc);
168→      }
169→    }
170→
171→    this.miniSearch.addAll(Array.from(deduped.values()));
172→    this.indexVersion++;
173→  }
174→
175→  /**
176→   * Search the index with fuzzy matching.
177→   *
178→   * @param query - user's search string
179→   * @returns Array of SearchResult sorted by relevance score (descending)
180→   */
181→  search(query: string): SearchResult[] {
182→    if (!query.trim()) return [];
183→
184→    const results = this.miniSearch.search(query);
185→
186→    return results.map((result) => ({
187→      id: result.id as string,
188→      name: result.name as string,
189→      type: result.type as 'file' | 'folder',
190→      parentPath: result.parentPath as string,
191→      parentFolderId: result.parentFolderId as string,
192→      modifiedAt: result.modifiedAt as number,
193→      score: result.score,
194→      match: result.match,
195→    }));
196→  }
197→
198→  /**
199→   * Persist the current index to IndexedDB, encrypted with a key derived
200→   * from the user's vault private key via HKDF.
201→   *
202→   * @param userPrivateKey - user's secp256k1 private key (32 bytes) for HKDF derivation
203→   */
204→  async persistEncrypted(userPrivateKey: Uint8Array): Promise<void> {
205→    try {
206→      const searchKey = await this.deriveSearchKey(userPrivateKey);
207→      const serialized = JSON.stringify(this.miniSearch.toJSON());
208→      const plaintext = new TextEncoder().encode(serialized);
209→
210→      const iv = crypto.getRandomValues(new Uint8Array(12));
211→      const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, searchKey, plaintext);
212→
213→      const db = await openSearchDB();
214→      const tx = db.transaction(IDB_STORE, 'readwrite');
215→      const store = tx.objectStore(IDB_STORE);
216→
217→      // Store as number[] for cross-browser IndexedDB compatibility
218→      store.put(
219→        {
220→          iv: Array.from(iv),
221→          data: Array.from(new Uint8Array(ciphertext)),
222→        },
223→        IDB_KEY
224→      );
225→
226→      await new Promise<void>((resolve, reject) => {
227→        tx.oncomplete = () => resolve();
228→        tx.onerror = () => reject(tx.error);
229→      });
230→    } catch (err) {
231→      console.warn('[SearchIndex] Failed to persist encrypted index:', err);
232→    }
233→  }
234→
235→  /**
236→   * Load the index from IndexedDB and decrypt.
237→   *
238→   * @param userPrivateKey - user's secp256k1 private key (32 bytes) for HKDF derivation
239→   * @returns true if index was loaded successfully, false if not found or decryption failed
240→   */
241→  async loadEncrypted(userPrivateKey: Uint8Array): Promise<boolean> {
242→    try {
243→      const db = await openSearchDB();
244→      const tx = db.transaction(IDB_STORE, 'readonly');
245→      const store = tx.objectStore(IDB_STORE);
246→
247→      const stored = await new Promise<{
248→        iv: number[];
249→        data: number[];
250→      } | null>((resolve, reject) => {
251→        const request = store.get(IDB_KEY);
252→        request.onsuccess = () => resolve(request.result ?? null);
253→        request.onerror = () => reject(request.error);
254→      });
255→
256→      if (!stored || !stored.iv || !stored.data) return false;
257→
258→      const searchKey = await this.deriveSearchKey(userPrivateKey);
259→      const iv = new Uint8Array(stored.iv);
260→      const ciphertext = new Uint8Array(stored.data);
261→
262→      const plaintext = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, searchKey, ciphertext);
263→
264→      const serialized = new TextDecoder().decode(plaintext);
265→      const json = JSON.parse(serialized);
266→
267→      this.miniSearch = MiniSearch.loadJSON(JSON.stringify(json), MINISEARCH_OPTIONS);
268→      return true;
269→    } catch (err) {
270→      console.warn('[SearchIndex] Failed to load encrypted index:', err);
271→      return false;
272→    }
273→  }
274→
275→  /**
276→   * Clear the in-memory index and remove the encrypted entry from IndexedDB.
277→   * Call on logout.
278→   */
279→  async clear(): Promise<void> {
280→    this.miniSearch.removeAll();
281→
282→    try {
283→      const db = await openSearchDB();
284→      const tx = db.transaction(IDB_STORE, 'readwrite');
285→      const store = tx.objectStore(IDB_STORE);
286→      store.delete(IDB_KEY);
287→
288→      await new Promise<void>((resolve, reject) => {
289→        tx.oncomplete = () => resolve();
290→        tx.onerror = () => reject(tx.error);
291→      });
292→    } catch (err) {
293→      console.warn('[SearchIndex] Failed to clear IndexedDB entry:', err);
294→    }
295→  }
296→
297→  /** Returns whether the index has any documents */
298→  get isEmpty(): boolean {
299→    return this.miniSearch.documentCount === 0;
300→  }
301→
302→  /** Returns the number of indexed documents */
303→  get size(): number {
304→    return this.miniSearch.documentCount;
305→  }
