268→
269→    // Verify palette closes
270→    await searchPalette.waitForClosed({ timeout: 5000 });
271→  });
272→
273→  // ============================================
274→  // 9. Cleanup
275→  // ============================================
276→
277→  test('9.1 Cleanup', async () => {
